function gerarHtmlImpressao(tipo) {
  const legendas = {
    triagem: "Legenda — Cond: F=Funcional, NF=Não Funcional. Status: R=Recuperado, SC=Sub-Conjunto, D=Desmontado, DC=Descarte. Destino: LJ=Loja Física, EG=Estoque Geral, EA=Estoque de Apoio.",
    requisicao: "Legenda — Fonte: INT=Estoque de Peças Boas, EXT=Compra Externa. Status: AG=Aguardando, SOL=Solicitado, RES=Reservado, REC=Recebido, APL=Aplicado.",
  };
  const titulos = {
    triagem: ["MAPA DIÁRIO DE TRIAGEM", "Preenchimento manual — um produto por linha"],
    desmontagem: ["ORDEM DE DESMONTAGEM", "Preenchimento manual — 1 formulário por produto"],
    requisicao: ["MAPA DIÁRIO DE REQUISIÇÃO DE PEÇAS", "Preenchimento manual — um item por linha"],
  };
  const colunasLista = {
    triagem: ["Nº", "SKU", "Descrição", "Cond.", "Status", "Destino / Peça Faltante", "Qtd.", "Obs."],
    requisicao: ["Nº", "ID do Produto", "Peça / Insumo Necessário", "Qtd.", "Fonte", "Status", "Data Prevista", "Obs."],
  };
  const [titulo, subtitulo] = titulos[tipo];
  const style = `
    body{font-family:Arial,sans-serif;color:#333;margin:20px;}
    .barra{background:#003D8D;color:#fff;padding:14px 18px;border-radius:8px;display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;}
    .barra h1{font-size:16px;margin:0;} .barra p{font-size:11px;margin:2px 0 0;color:#BFD3EE;}
    .legenda{font-size:10px;color:#666;font-style:italic;margin-bottom:10px;}
    table{width:100%;border-collapse:collapse;font-size:11px;}
    th,td{border:1px solid #999;padding:5px;text-align:left;}
    th{background:#eef1f6;}
    td{height:22px;}
    .info{font-size:11px;margin-bottom:10px;}
    @media print { @page { size: A4 landscape; margin: 10mm; } }
  `;
  let corpo = `<div class="barra"><div><h1>PENTÁGONO OUTLET DE ELETRODOMÉSTICOS</h1></div><div style="text-align:right"><h1>${titulo}</h1><p>${subtitulo}</p></div></div>`;
  corpo += `<div class="info">Data: ____/____/______ &nbsp;&nbsp;&nbsp; Técnico(s): _______________________ &nbsp;&nbsp;&nbsp; Folha nº: _______</div>`;

  if (tipo === "desmontagem") {
    corpo += `<div class="info">ID do Produto de Origem: _______________________ &nbsp;&nbsp;&nbsp; Nº do formulário: OD-________</div>`;
    corpo += `<table><thead><tr><th>Descrição da Peça</th><th>Categoria</th><th>Condição</th><th>Qtd.</th><th>Destino Previsto</th></tr></thead><tbody>`;
    for (let i = 0; i < 10; i++) corpo += `<tr><td></td><td></td><td></td><td></td><td></td></tr>`;
    corpo += `</tbody></table>`;
  } else {
    corpo += `<div class="legenda">${legendas[tipo]}</div>`;
    const cols = colunasLista[tipo];
    corpo += `<table><thead><tr>${cols.map((c) => `<th>${c}</th>`).join("")}</tr></thead><tbody>`;
    for (let i = 1; i <= 17; i++) {
      corpo += `<tr><td>${i}</td>${cols.slice(1).map(() => "<td></td>").join("")}</tr>`;
    }
    corpo += `</tbody></table>`;
  }
  return `<html><head><title>${titulo}</title><style>${style}</style></head><body>${corpo}</body></html>`;
}

function agruparRecuperados(produtos) {
  const grupos = {};
  produtos.filter((p) => p.status === "Recuperado").forEach((p) => {
    const key = p.codigoFornecedor + "|" + p.descricao;
    if (!grupos[key]) grupos[key] = { codigoFornecedor: p.codigoFornecedor, descricao: p.descricao, quantidade: 0, valorTotal: 0 };
    grupos[key].quantidade += 1;
    grupos[key].valorTotal += (p.valorVenda || 0);
  });
  return Object.values(grupos)
    .map((g) => ({ ...g, valorUnitMedio: g.quantidade ? g.valorTotal / g.quantidade : 0 }))
    .sort((a, b) => b.quantidade - a.quantidade);
}

const RECUPERADOS_EXPORT_MAP = {
  codigoFornecedor: "Código_Fornecedor", descricao: "Descrição", quantidade: "Quantidade",
  valorUnitMedio: "Valor_Unitário_Médio", valorTotal: "Valor_Total",
};

function gerarHtmlRecuperados(db) {
  const linhas = agruparRecuperados(db.produtos);
  const totalUnidades = linhas.reduce((s, l) => s + l.quantidade, 0);
  const totalValor = linhas.reduce((s, l) => s + l.valorTotal, 0);
  const style = `
    body{font-family:Arial,sans-serif;color:#333;margin:20px;}
    .barra{background:#003D8D;color:#fff;padding:14px 18px;border-radius:8px;display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;}
    .barra h1{font-size:16px;margin:0;} .barra p{font-size:11px;margin:2px 0 0;color:#BFD3EE;}
    table{width:100%;border-collapse:collapse;font-size:11px;}
    th,td{border:1px solid #999;padding:5px;text-align:left;}
    th{background:#eef1f6;} td.num{text-align:right;}
    tfoot td{font-weight:bold;border-top:2px solid #003D8D;}
    @media print { @page { size: A4 portrait; margin: 12mm; } }
  `;
  let corpo = `<div class="barra"><div><h1>PENTÁGONO OUTLET DE ELETRODOMÉSTICOS</h1></div><div style="text-align:right"><h1>RELATÓRIO DE PRODUTOS RECUPERADOS</h1><p>Gerado em ${todayStr()} — agrupado por código</p></div></div>`;
  corpo += `<table><thead><tr><th>Código</th><th>Descrição</th><th>Qtd.</th><th>Valor Unit. (médio)</th><th>Valor Total</th></tr></thead><tbody>`;
  linhas.forEach((l) => {
    corpo += `<tr><td>${l.codigoFornecedor}</td><td>${l.descricao}</td><td class="num">${l.quantidade}</td><td class="num">${l.valorUnitMedio ? "R$ " + l.valorUnitMedio.toFixed(2) : "-"}</td><td class="num">${l.valorTotal ? "R$ " + l.valorTotal.toFixed(2) : "-"}</td></tr>`;
  });
  if (linhas.length === 0) corpo += `<tr><td colspan="5" style="text-align:center;color:#999;">Nenhum produto recuperado ainda.</td></tr>`;
  corpo += `</tbody>`;
  if (linhas.length > 0) {
    corpo += `<tfoot><tr><td colspan="2">Total</td><td class="num">${totalUnidades}</td><td></td><td class="num">R$ ${totalValor.toFixed(2)}</td></tr></tfoot>`;
  }
  corpo += `</table>`;
  return `<html><head><title>Relatório de Recuperados</title><style>${style}</style></head><body>${corpo}</body></html>`;
}

function RelatorioRecuperadosImpresso({ db }) {
  const linhas = agruparRecuperados(db.produtos);
  const totalUnidades = linhas.reduce((s, l) => s + l.quantidade, 0);
  const totalValor = linhas.reduce((s, l) => s + l.valorTotal, 0);
  const tdDados = "border border-slate-300 px-1.5 py-1.5 text-slate-700";

  return (
    <div>
      <ImpressoHeader title="RELATÓRIO DE PRODUTOS RECUPERADOS" subtitle={`Gerado em ${todayStr()} — agrupado por código`} />
      <table className="w-full text-[11px] border-collapse border border-slate-400">
        <thead>
          <tr>
            <th className={thCls}>Código</th>
            <th className={thCls}>Descrição</th>
            <th className={thCls + " w-16 text-right"}>Qtd.</th>
            <th className={thCls + " w-24 text-right"}>Valor Unit. (méd.)</th>
            <th className={thCls + " w-24 text-right"}>Valor Total</th>
          </tr>
        </thead>
        <tbody>
          {linhas.map((l, i) => (
            <tr key={i}>
              <td className={tdDados + " font-mono"}>{l.codigoFornecedor}</td>
              <td className={tdDados}>{l.descricao}</td>
              <td className={tdDados + " text-right"}>{l.quantidade}</td>
              <td className={tdDados + " text-right"}>{l.valorUnitMedio ? "R$ " + l.valorUnitMedio.toFixed(2) : "-"}</td>
              <td className={tdDados + " text-right"}>{l.valorTotal ? "R$ " + l.valorTotal.toFixed(2) : "-"}</td>
            </tr>
          ))}
          {linhas.length === 0 && (
            <tr><td colSpan={5} className="text-center py-4 text-slate-400 border border-slate-300">Nenhum produto recuperado ainda.</td></tr>
          )}
        </tbody>
        {linhas.length > 0 && (
          <tfoot>
            <tr className="font-semibold">
              <td className={tdDados} colSpan={2}>Total</td>
              <td className={tdDados + " text-right"}>{totalUnidades}</td>
              <td className={tdDados}></td>
              <td className={tdDados + " text-right"}>R$ {totalValor.toFixed(2)}</td>
            </tr>
          </tfoot>
        )}
      </table>
    </div>
  );
}

function Imprimir({ db }) {
  const [formSel, setFormSel] = useState("triagem");
  const [avisoPopup, setAvisoPopup] = useState(false);
  const opcoes = [
    { id: "triagem", label: "Mapa de Triagem" },
    { id: "desmontagem", label: "Ordem de Desmontagem" },
    { id: "requisicao", label: "Mapa de Requisição" },
    { id: "recuperados", label: "Relatório de Recuperados" },
  ];

  function abrirParaImprimir() {
    setAvisoPopup(false);
    const html = formSel === "recuperados" ? gerarHtmlRecuperados(db) : gerarHtmlImpressao(formSel);
    const win = window.open("", "_blank", "width=1000,height=700");
    if (!win) {
      setAvisoPopup(true);
      return;
    }
    win.document.open();
    win.document.write(html);
    win.document.close();
    win.focus();
    setTimeout(() => { try { win.print(); } catch (e) { /* usuário pode imprimir manualmente pela janela aberta */ } }, 400);
  }

  return (
    <div className="space-y-4">
      <Card className="p-4 no-print">
        <h2 className="font-semibold mb-1">Imprimir formulário em branco</h2>
        <p className="text-sm text-slate-500 mb-3">
          Escolha o formulário e clique em Imprimir. Para uma versão com mais linhas por folha (formato paisagem já pronto),
          use o PDF de formulários já gerado anteriormente.
        </p>
        <div className="flex flex-wrap gap-2 mb-3">
          {opcoes.map((o) => (
            <button
              key={o.id}
              onClick={() => setFormSel(o.id)}
              className={`text-sm px-3 py-2 rounded-lg border ${formSel === o.id ? "brand-btn brand-border-color" : "border-slate-300 hover:bg-slate-50"}`}
            >
              {o.label}
            </button>
          ))}
        </div>
        <div className="flex flex-wrap gap-2 items-center">
          <button onClick={() => window.print()} className="brand-btn rounded-lg px-4 py-2.5 text-sm font-medium flex items-center gap-1.5">
            <Printer size={16} /> Imprimir agora
          </button>
          <button onClick={abrirParaImprimir} className="text-sm border border-slate-300 rounded-lg px-4 py-2.5 hover:bg-slate-50 flex items-center gap-1.5">
            <Printer size={16} /> Abrir em nova janela para imprimir
          </button>
          {formSel === "recuperados" && (
            <button
              onClick={() => downloadCSV("relatorio_recuperados.csv", mapRowsForExport(agruparRecuperados(db.produtos), RECUPERADOS_EXPORT_MAP))}
              className="text-sm border border-slate-300 rounded-lg px-4 py-2.5 hover:bg-slate-50 flex items-center gap-1.5"
            >
              <Download size={16} /> Baixar como CSV
            </button>
          )}
        </div>
        {avisoPopup && (
          <div className="mt-3 text-sm text-amber-800 bg-amber-50 border border-amber-300 rounded-lg p-3">
            Seu navegador bloqueou a nova janela (pop-up). Procure um ícone de bloqueio na barra de endereço e permita
            pop-ups para este site, depois tente de novo. Se continuar bloqueado, use o PDF de formulários já pronto.
          </div>
        )}
      </Card>

      <div className="print-page bg-white rounded-xl border border-slate-200 p-6">
        {formSel === "triagem" && <FormularioTriagemImpresso />}
        {formSel === "desmontagem" && <FormularioDesmontagemImpresso />}
        {formSel === "requisicao" && <FormularioRequisicaoImpresso />}
        {formSel === "recuperados" && <RelatorioRecuperadosImpresso db={db} />}
      </div>
    </div>
  );
}

// ---------------- CONFIGURAÇÕES ----------------

function Configuracoes({ db, onReset }) {
  const [etapa, setEtapa] = useState(0); // 0 = normal, 1 = pedindo confirmação, 2 = pedindo digitar palavra
  const [textoDigitado, setTextoDigitado] = useState("");
  const [limpando, setLimpando] = useState(false);
  const [feito, setFeito] = useState(false);

  const totalRegistros = db.produtos.length + db.historico.length + db.pecasBoas.length + db.pecasFaltantes.length;

  async function confirmarLimpeza() {
    setLimpando(true);
    await onReset();
    setLimpando(false);
    setFeito(true);
    setEtapa(0);
    setTextoDigitado("");
  }

  return (
    <div className="space-y-4 max-w-2xl">
      <Card className="p-5">
        <h2 className="font-semibold mb-1">Resumo do que está salvo agora</h2>
        <p className="text-sm text-slate-500 mb-3">Use isto para conferir se ainda são dados de teste antes de zerar.</p>
        <div className="grid grid-cols-2 gap-2 text-sm">
          <div className="border border-slate-200 rounded-lg p-3"><div className="text-slate-500 text-xs">Produtos</div><div className="text-lg font-semibold">{db.produtos.length}</div></div>
          <div className="border border-slate-200 rounded-lg p-3"><div className="text-slate-500 text-xs">Movimentações no Histórico</div><div className="text-lg font-semibold">{db.historico.length}</div></div>
          <div className="border border-slate-200 rounded-lg p-3"><div className="text-slate-500 text-xs">Peças Boas em estoque</div><div className="text-lg font-semibold">{db.pecasBoas.length}</div></div>
          <div className="border border-slate-200 rounded-lg p-3"><div className="text-slate-500 text-xs">Necessidades de Peças</div><div className="text-lg font-semibold">{db.pecasFaltantes.length}</div></div>
        </div>
      </Card>

      <Card className="p-5 border-rose-300">
        <div className="flex items-center gap-2 mb-1">
          <ShieldAlert size={18} className="text-rose-600" />
          <h2 className="font-semibold text-rose-700">Zona de risco — apagar todos os dados</h2>
        </div>
        <p className="text-sm text-slate-500 mb-4">
          Isso remove permanentemente todos os {totalRegistros} registro(s) de teste (produtos, histórico, peças) e deixa o
          sistema como novo, pronto para lançamentos reais. <strong>Não tem como desfazer.</strong> Recomendado só depois de
          confirmar que o app está funcionando corretamente com você.
        </p>

        {feito && (
          <div className="border border-emerald-300 bg-emerald-50 rounded-lg p-3 mb-3 flex items-center gap-2 text-sm text-emerald-800">
            <CheckCircle2 size={18} className="text-emerald-600" /> Dados apagados. Sistema zerado e pronto para uso real.
          </div>
        )}

        {etapa === 0 && (
          <button onClick={() => setEtapa(1)} className="text-sm bg-rose-600 text-white rounded-lg px-4 py-2.5 hover:bg-rose-700 flex items-center gap-1.5">
            <Trash2 size={15} /> Quero apagar todos os dados de teste
          </button>
        )}

        {etapa === 1 && (
          <div className="border border-rose-300 bg-rose-50 rounded-lg p-3">
            <p className="text-sm text-rose-800 mb-3">
              Tem certeza? Isso apaga {totalRegistros} registro(s) permanentemente para todos que usam este sistema.
            </p>
            <div className="flex gap-2">
              <button onClick={() => setEtapa(2)} className="text-sm bg-rose-600 text-white rounded-lg px-3 py-2 hover:bg-rose-700">Sim, continuar</button>
              <button onClick={() => setEtapa(0)} className="text-sm border border-slate-300 rounded-lg px-3 py-2 hover:bg-white">Cancelar</button>
            </div>
          </div>
        )}

        {etapa === 2 && (
          <div className="border border-rose-300 bg-rose-50 rounded-lg p-3">
            <p className="text-sm text-rose-800 mb-2">
              Última confirmação — digite a palavra <span className="font-mono font-bold">APAGAR</span> na caixa abaixo:
            </p>
            <input className={inputCls + " mb-2"} value={textoDigitado} onChange={(e) => setTextoDigitado(e.target.value)} placeholder="Digite APAGAR" />
            <div className="flex gap-2">
              <button
                onClick={confirmarLimpeza}
                disabled={textoDigitado !== "APAGAR" || limpando}
                className="text-sm bg-rose-600 text-white rounded-lg px-3 py-2 hover:bg-rose-700 disabled:opacity-40 flex items-center gap-1.5"
              >
                {limpando ? <><Loader2 size={14} className="animate-spin" /> Apagando...</> : <>Apagar definitivamente</>}
              </button>
              <button onClick={() => { setEtapa(0); setTextoDigitado(""); }} className="text-sm border border-slate-300 rounded-lg px-3 py-2 hover:bg-white">Cancelar</button>
            </div>
          </div>
        )}
      </Card>
    </div>
  );
}

function Historico({ db }) {
  const [busca, setBusca] = useState("");
  const filtrado = db.historico.filter((h) => !busca || h.idItem.toLowerCase().includes(busca.toLowerCase()));
  return (
    <Card className="p-4">
      <div className="relative mb-3 max-w-sm">
        <Search size={15} className="absolute left-2.5 top-2.5 text-slate-400" />
        <input className={inputCls + " pl-8"} placeholder="Buscar por ID do item..." value={busca} onChange={(e) => setBusca(e.target.value)} />
      </div>
      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead>
            <tr className="text-left text-xs text-slate-500 border-b border-slate-200">
              <th className="py-2 pr-3">Data/Hora</th>
              <th className="py-2 pr-3">Item</th>
              <th className="py-2 pr-3">De → Para</th>
              <th className="py-2 pr-3">Estoque</th>
              <th className="py-2 pr-3">Responsável</th>
              <th className="py-2 pr-3">Documento</th>
              <th className="py-2 pr-3">Motivo</th>
            </tr>
          </thead>
          <tbody>
            {filtrado.map((h) => (
              <tr key={h.id} className="border-b border-slate-100 last:border-0 align-top">
                <td className="py-2 pr-3 whitespace-nowrap text-slate-500">{h.dataHora}</td>
                <td className="py-2 pr-3 font-mono text-xs">{h.idItem}</td>
                <td className="py-2 pr-3 whitespace-nowrap">{h.statusAnterior} → <strong>{h.statusNovo}</strong></td>
                <td className="py-2 pr-3 text-slate-500 whitespace-nowrap">{h.estoqueDestino}</td>
                <td className="py-2 pr-3">{h.responsavel}</td>
                <td className="py-2 pr-3 font-mono text-xs">{h.documento}</td>
                <td className="py-2 pr-3 text-slate-500">{h.motivo}</td>
              </tr>
            ))}
            {filtrado.length === 0 && (
              <tr><td colSpan={7} className="py-8 text-center text-slate-400">Nenhuma movimentação registrada ainda.</td></tr>
            )}
          </tbody>
        </table>
      </div>
    </Card>
  );
}
